package com.sunrise.dentalclinic;
import com.sunrise.dentalclinic.model.*;import com.sunrise.dentalclinic.repository.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import java.math.BigDecimal;import java.time.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestBuilders.formLogin;import static org.springframework.security.test.web.servlet.response.SecurityMockMvcResultMatchers.authenticated;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class SecurityAndApiTest{@Autowired MockMvc mvc;@Autowired UserRepository users;@Autowired PatientRepository patients;@Autowired DentistRepository dentists;@Autowired TreatmentRepository treatments;@Autowired PasswordEncoder encoder;
 @BeforeEach void seedUser(){if(users.findByUsernameIgnoreCase("staff").isEmpty()){var u=new User();u.setUsername("staff");u.setFullName("Test Staff");u.setPasswordHash(encoder.encode("safe-test-password"));u.setRole(Role.STAFF);u.setEnabled(true);users.save(u);}}
 @Test void protectedPageRedirectsAnonymousToLogin()throws Exception{mvc.perform(get("/dashboard")).andExpect(status().is3xxRedirection());}
 @Test void validLoginCanAccessDashboard()throws Exception{mvc.perform(formLogin().user("staff").password("safe-test-password")).andExpect(authenticated().withUsername("staff"));}
 @Test void restValidationReturnsSafeBadRequest()throws Exception{mvc.perform(post("/api/v1/appointments").with(user("staff").roles("STAFF")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.error").value("Validation failed"));}
 @Test void createsAppointmentThroughRest()throws Exception{var p=new Patient();p.setName("API Patient");p.setAddress("Colombo");p.setContactNumber("0771234567");p=patients.save(p);var d=new Dentist();d.setName("Dr Test");d.setSpecialization("General");d=dentists.save(d);var t=new Treatment();t.setTreatmentName("Checkup");t.setTreatmentCost(new BigDecimal("2500.00"));t=treatments.save(t);String body="{\"patientId\":"+p.getId()+",\"dentistId\":"+d.getId()+",\"treatmentId\":"+t.getId()+",\"appointmentDate\":\""+LocalDate.now().plusDays(1)+"\",\"appointmentTime\":\"09:00\",\"notes\":\"API test\"}";mvc.perform(post("/api/v1/appointments").with(user("staff").roles("STAFF")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.appointmentNumber").exists());}}
